function normName(v: string): string {
  return v.replace(/\s+/g, " ").trim().toUpperCase();
}

/** Nomor klaster acuan Excel untuk satu kelompok pada K tertentu (nama siswa → klaster). */
export function excelClusterMap(group: string, k: number): Map<string, number> | null {
  const ref = EXCEL_CLUSTERS[group];
  const arr = ref?.byK?.[k];
  if (!ref || !arr) return null;
  const map = new Map<string, number>();
  ref.names.forEach((n, i) => map.set(normName(n), arr[i]));
  return map;
}

export { normName as normalizeSiswaName };

